import{_ as s,o as a,c as n,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const r=JSON.parse('{"title":"第七章 回归分析","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/07-第七章-回归分析.md","filePath":"tutorial/07-第七章-回归分析.md","lastUpdated":1785684581000}'),p={name:"tutorial/07-第七章-回归分析.md"};function c(d,e,t,i,l,S){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="第七章-回归分析" tabindex="-1">第七章 回归分析 <a class="header-anchor" href="#第七章-回归分析" aria-label="Permalink to &quot;第七章 回归分析&quot;">​</a></h1><p>回到第六章末尾那句判断：单因素方差分析把分类因素编码为虚拟变量之后，与线性回归在数学上并无二致。那一章处理的是&quot;不同组的均值是否相等&quot;，本章则把问题往前推一步——不再满足于比较是否不同，而是试着用一个或几个变量去预测另一个变量，并量化预测能有多准。这一族方法（相关与回归）和方差分析共享同一个理论底座，即一般线性模型（general linear model）；差别只在自变量是连续还是分类、目标是有方向地预测还是对称地度量关联。</p><p>本章先以 <code>CORRELATIONS</code> 探查变量间的线性联动，再用 <code>REGRESSION</code> 建立可预测的线性模型，最后直面 PSPP 在回归诊断上的能力边界。所用示例数据均为虚构，思路参考 PSPP 随附的 physiology.sav，仅用于教学，不可用作研究结论。</p><h2 id="_7-1-相关分析与回归分析的关系定位" tabindex="-1">7.1 相关分析与回归分析的关系定位 <a class="header-anchor" href="#_7-1-相关分析与回归分析的关系定位" aria-label="Permalink to &quot;7.1 相关分析与回归分析的关系定位&quot;">​</a></h2><p>相关分析与回归分析常被放在同一章讲述，却承担不同的分工。相关分析回答&quot;两个变量是否同步变动、联动有多紧密&quot;，它本身不区分谁预测谁；回归分析回答&quot;已知若干变量，能否预测另一个变量、预测误差有多大&quot;，它明确区分因变量与自变量。一句话，相关描述关系，回归把关系变成可操作的预测方程。</p><p>两者之所以能同框，根子在于它们都是一般线性模型的特例。第六章已提到，把分类因素编码为虚拟变量后，方差分析的 F 检验与回归的 F 检验在数学上完全等价；事实上，相关、回归、方差分析都建立在同一条线性代数主线上：用一组自变量的线性组合去逼近因变量，再把总变异拆成&quot;被模型解释&quot;和&quot;未被解释（残差）&quot;两部分。第六章借 <code>GLM</code> 统一承载多因素设计，正是因为一般线性模型把这些都收编进了同一框架。</p><p>具体而言，Pearson 相关与简单回归之间的纽带非常直接。当只有一个自变量时，回归得到的标准化系数 Beta 的绝对值恰好等于相关系数 r；非标准化系数 B 与 r、各自的标准差之间也存在确定换算。不过两者的取向并不相同：相关是对称的，r(height, weight) 与 r(weight, height) 完全相同，没有方向；回归是不对称的，必须事先指定哪个是自变量、哪个是因变量，得到的是&quot;由 X 预测 Y&quot;的一条方程。相关只告诉你&quot;有没有关系、有多强&quot;，回归进一步告诉你&quot;若 X 变动一单位，Y 平均变动多少&quot;。</p><p>回归把&quot;预测一个连续变量&quot;这件事形式化，靠的是一条直线方程与一种估计准则。模型写作：</p><p>y = β₀ + β₁x₁ + … + βₖxₖ + ε</p><p>其中 β₀ 是截距，β₁…βₖ 是各自变量的系数，ε 是残差。估计系数的准则通常是普通最小二乘法（ordinary least squares，OLS），即让所有个案残差的平方和达到最小。这样一来，&quot;预测&quot;就从直觉变成了可估计、可检验、可横向比较的对象——这正是回归相对于单纯相关多出的一块能力。</p><p>实践里到底该先跑相关还是直接上回归，取决于研究问题有没有预设方向。若只想确认两个变量是否联动、并不打算由一方去预测另一方，相关足以胜任；若研究本就带着&quot;用 X 估计 Y&quot;的目的，应当直接建立回归，相关至多作为前置的直观体检。二者并不互斥：先以相关窥探变量间的线性强度，再以回归给出可操作的预测方程，是常见且稳妥的工作流。</p><p>阅读本章时，有两条跨章线索值得记住。其一，相关分析呼应第四章描述统计：在盯着相关系数之前，应当先看各变量的均值与标准差（第四章的 <code>DESCRIPTIVES</code>），确认变量的尺度与分布是否支撑后续的线性度量。其二，回归与第六章方差分析血脉相连：两者都用 F 检验判断&quot;模型是否显著优于仅凭均值预测&quot;，都倚赖残差概念衡量未能解释的变异；回归里的 <code>R²</code> 与 ANOVA 里的&quot;组间变异占总变异之比&quot;在精神上一脉相承。</p><h2 id="_7-2-相关分析-correlations" tabindex="-1">7.2 相关分析 CORRELATIONS <a class="header-anchor" href="#_7-2-相关分析-correlations" aria-label="Permalink to &quot;7.2 相关分析 CORRELATIONS&quot;">​</a></h2><p><code>CORRELATIONS</code> 计算变量两两之间的 Pearson 积矩相关系数。图形界面下它位于菜单 Analyze → Correlate → Bivariate（界面推断，手册未逐项文档化）。最常用、也最清晰的做法仍是直接书写语法：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CORRELATIONS /VARIABLES=height weight</span></span>
<span class="line"><span>            /PRINT=TWOTAIL SIG</span></span>
<span class="line"><span>            /STATISTICS=DESCRIPTIVES.</span></span></code></pre></div><p><code>/VARIABLES</code> 之后罗列参与分析的变量，命令会输出它们之间的对称相关矩阵。若改用 <code>/VARIABLES=v1 WITH v2 v3</code> 的形式，则只计算 v1 与后两者之间的相关，得到的是非方阵而非完整交叉表。这一写法在只想看某个核心变量与其余变量关联时尤其省心。</p><p><code>/PRINT</code> 控制检验方向与显著性呈现：可取的选项是 <code>{TWOTAIL, ONETAIL}</code> 与 <code>{SIG, NOSIG}</code>。<code>TWOTAIL</code> 表示双尾检验，<code>SIG</code> 会在 p 值低于 0.05 时把该相关高亮提示；命令默认即为 <code>TWOTAIL</code> 与 <code>NOSIG</code>（即不显示显著性，只给系数）。<code>/STATISTICS=DESCRIPTIVES</code> 会在相关矩阵之前附上各变量的均值、标准差与有效个案数，便于读者先确认样本规模与量纲。<code>/MISSING</code> 默认为 <code>PAIRWISE</code>（成对删除，即每一对相关只用同时有效的个案计算），也可改为 <code>LISTWISE</code>（整例删除，凡含任意缺失值的个案一律剔除）。成对删除能尽量保住样本，但不同相关所用的有效个案数可能不同，比较矩阵时须留意样本量一行；整例删除则保证所有系数基于同一批个案，代价是可能浪费数据。两者取舍没有绝对优劣，关键是报告时如实说明采用了哪一种。</p><p><code>CORRELATIONS</code> 计算的始终是 Pearson 相关，它衡量的是两个变量的线性关系强度。系数 r 落在 -1 到 1 之间：符号指示方向，正值为同向变动、负值为反向变动；绝对值指示强度，越接近 1 线性关联越紧，接近 0 则几乎呈水平散乱。与 r 一并给出的 p 值回答&quot;样本中观测到的关联是否可能纯粹出于偶然&quot;——当 p 小于所选 α（通常 0.05），才可认为该相关在统计上区别于 0。</p><p>解读相关时有两个易踩的坑。第一，r 的平方（决定系数）才刻画两个变量共享的方差比例，是一个可用的效应量：r 仅为 0.5 时共享方差约 25%，中等强度的相关远非&quot;解释了一半&quot;。第二，也是最根本的一条——<strong>相关不等于因果</strong>。r 显著只说明两变量同步变化，它既不区分方向，也不能断言&quot;是 X 导致 Y&quot;。若要论证因果，还需实验设计或理论支撑，这已超出 <code>CORRELATIONS</code> 的本领。</p><p>在敲下相关命令之前，先用散点图直观确认关系形态是稳妥的习惯。<code>GRAPH</code> 一次只绘制一种图形，散点图这样写（菜单路径推断为 Graphs → Legacy Dialogs → Scatter/Dot，界面推断，手册未逐项文档化）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GRAPH /SCATTERPLOT = height WITH weight.</span></span></code></pre></div><p>若散点明显沿一条斜带分布，说明线性假设大致成立，Pearson r 才有意义；若呈曲线、团块或离散点阵，则 r 会低估甚至掩盖真实关系，此时应考虑变换变量或改用非线性方法。</p><p>下面构造一份虚构数据集，记录 12 名个体的身高（厘米）与体重（千克），演示相关分析：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST /id (A4) height (F4.0) weight (F4.0).</span></span>
<span class="line"><span>BEGIN DATA.</span></span>
<span class="line"><span>P001 172 65</span></span>
<span class="line"><span>P002 168 60</span></span>
<span class="line"><span>P003 180 75</span></span>
<span class="line"><span>P004 160 52</span></span>
<span class="line"><span>P005 175 70</span></span>
<span class="line"><span>P006 165 58</span></span>
<span class="line"><span>P007 178 72</span></span>
<span class="line"><span>P008 158 50</span></span>
<span class="line"><span>P009 170 63</span></span>
<span class="line"><span>P010 182 78</span></span>
<span class="line"><span>P011 166 57</span></span>
<span class="line"><span>P012 174 68</span></span>
<span class="line"><span>END DATA.</span></span>
<span class="line"><span>VARIABLE LABELS height &#39;身高(厘米)&#39; weight &#39;体重(千克)&#39;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GRAPH /SCATTERPLOT = height WITH weight.</span></span>
<span class="line"><span>CORRELATIONS /VARIABLES=height weight</span></span>
<span class="line"><span>            /PRINT=TWOTAIL SIG</span></span>
<span class="line"><span>            /STATISTICS=DESCRIPTIVES.</span></span></code></pre></div><p>结果解读要点：散点图应呈现从左下到右上的斜带；相关矩阵中 height 与 weight 的 r 通常落在 0.9 附近，且 <code>SIG</code> 远小于 0.05，表明身高与体重的线性关联在本样本里既强又显著。<code>/STATISTICS=DESCRIPTIVES</code> 输出的均值与标准差则给出变量的集中与离散概况。务必补一句：相关显著不等于因果，它只说明两变量同步变化，不能断言&quot;长高导致变重&quot;。</p><h2 id="_7-3-简单线性回归-regression" tabindex="-1">7.3 简单线性回归 REGRESSION <a class="header-anchor" href="#_7-3-简单线性回归-regression" aria-label="Permalink to &quot;7.3 简单线性回归 REGRESSION&quot;">​</a></h2><p>把&quot;由身高预测体重&quot;从相关推进到一条具体方程，用的就是 <code>REGRESSION</code>。图形界面下它位于菜单 Analyze → Regression → Linear（界面推断，手册未逐项文档化）。一元（简单）线性回归的语法结构如下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGRESSION /VARIABLES=height weight /DEPENDENT=weight</span></span>
<span class="line"><span>           /STATISTICS=DEFAULTS</span></span>
<span class="line"><span>           /SAVE=PRED RESID /METHOD=ENTER.</span></span></code></pre></div><p>这条语法的几个要点需要逐一交代。<code>/VARIABLES</code> 与 <code>/DEPENDENT</code> 都是必填项：前者列出全部变量，后者指定因变量；凡列在 <code>/VARIABLES</code> 中却没有出现在 <code>/DEPENDENT</code> 里的变量，一律被当作自变量——本例里 height 因此成为唯一的预测变量。<code>/STATISTICS</code> 决定输出哪些结果块，可取值为 <code>{ALL, DEFAULTS, R, COEFF, ANOVA, BCOV, CI[conf, TOL]}</code>；其中 <code>DEFAULTS</code> 等价于同时请求 <code>R</code>、<code>COEFF</code>、<code>ANOVA</code>，恰好覆盖模型解读所需的三块核心输出。<code>/ORIGIN</code> 与 <code>/NOORIGIN</code> 控制是否强制回归线经过原点，默认是 <code>/NOORIGIN</code>，即保留截距项；除非有充分的理论依据要求方程过零点，否则保留默认，切勿随手改为 <code>/ORIGIN</code> 而误删截距。若需要未标准化系数的方差—协方差矩阵，可在 <code>/STATISTICS</code> 追加 <code>BCOV</code>，它给出各系数估计之间的协方差结构，对理解系数估计的相互联系也有帮助。最后，<code>/SAVE=PRED RESID</code> 把预测值（新变量 <code>PRED1</code>）与残差（新变量 <code>RES1</code>）写回活动数据集，为 7.5 节的诊断做准备；多个变量时按先后次序编号。<code>/METHOD=ENTER</code> 表示将所有自变量一次性强制纳入，不做逐步筛选。</p><p>沿用 7.2 的数据集，直接运行上面这段语法即可。结果由三张表承载，解读时各有侧重：</p><ul><li><strong>模型汇总（Model Summary）</strong>：给出 <code>R</code>（复相关系数，一元情形下等于 |r|）与 <code>R²</code>（决定系数），<code>R²</code> 衡量因变量的变异中有多少比例被模型解释，是回归里最常用的效应量；该表还给出估计标准误（Std. Error of the Estimate），即残差标准差的估计，刻画预测值偏离真实值的典型幅度，该值越小预测越紧凑。</li><li><strong>ANOVA 表</strong>：报告整体 F 检验，其 <code>SIG</code> 回答&quot;模型整体上是否显著优于仅凭均值预测&quot;。当 <code>SIG</code> 远小于 0.05，可认为回归方程确有解释力。</li><li><strong>系数表（Coefficients）</strong>：核心所在，给出常数（截距）与自变量的非标准化系数 <code>B</code>、标准化系数 <code>Beta</code>、标准误、t 值与 <code>SIG</code>。以 <code>体重 = B₀ + B₁×身高</code> 为例，<code>B₀</code> 为截距、<code>B₁</code> 为斜率，含义是身高每变动一单位、体重平均变动多少千克；<code>SIG</code> 判断该自变量的回归系数是否显著区别于 0。一元情形下 <code>Beta</code> 的绝对值恰好等于相关系数 r。</li></ul><p>解读要点：若 <code>R²</code> 接近 0.8，意味着身高独自解释了体重约八成的变异，决定系数这一效应量相当可观；ANOVA 表的 F 检验 <code>SIG</code> 应远小于 0.05，确认模型整体有效；系数表中 height 的 <code>B</code> 通常在 0.7~0.9 区间，可表述为&quot;身高每增加 1 厘米，体重平均增加约 B 千克&quot;，其 <code>SIG</code> 小于 0.05 说明该斜率在统计上显著。此时 <code>PRED1</code> 与 <code>RES1</code> 已写入数据集，可在数据视图查看每个个案的预测值与残差。</p><h2 id="_7-4-多元回归与模型解读" tabindex="-1">7.4 多元回归与模型解读 <a class="header-anchor" href="#_7-4-多元回归与模型解读" aria-label="Permalink to &quot;7.4 多元回归与模型解读&quot;">​</a></h2><p>现实问题很少只受单一因素支配。多元回归把两个及以上自变量同时放进模型，估计在控制其他变量之后，每个自变量的独立贡献。语法与一元模型几乎一致，只需在 <code>/VARIABLES</code> 增加变量；若要顺带做共线性诊断，可在 <code>/STATISTICS</code> 追加 <code>TOL</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGRESSION /VARIABLES=height weight age /DEPENDENT=weight</span></span>
<span class="line"><span>           /STATISTICS=DEFAULTS TOL</span></span>
<span class="line"><span>           /SAVE=PRED RESID /METHOD=ENTER.</span></span></code></pre></div><p>这里 <code>age</code> 作为新增自变量进入模型。需要留意，<code>TOL</code> 仅在同时请求 <code>COEFF</code> 时才有效；由于 <code>DEFAULTS</code> 已经包含 <code>COEFF</code>，故 <code>TOL</code> 能正常产出。PSPP 不直接输出方差膨胀因子（VIF），但 <code>VIF = 1 / TOL</code>，拿到容忍度后手算即可。</p><p>多元回归的输出沿用 7.3 的三张表，但解读角度要补三件事。</p><p><strong>系数表</strong>在多元场景里尤为重要。非标准化系数 <code>B</code> 表示在控制其他自变量后，该自变量每变动一单位、因变量平均变动多少；它的实际单位仍是因变量的量纲，便于直接解释。标准化系数 <code>Beta</code> 则把所有变量先标准化到同一量纲后再估计，因而可在不同自变量之间比较&quot;谁的影响相对更大&quot;——比如比较身高（厘米）与年龄（岁）对体重的相对贡献时，<code>Beta</code> 比 <code>B</code> 更有可比性。每行仍附标准误、t 值与 <code>SIG</code>，分别用于判断单个系数是否显著区别于 0。</p><p><strong>模型汇总</strong>在多元场景里出现两个决定系数：<code>R²</code> 与调整 <code>R²</code>（Adjusted R Square）。<code>R²</code> 随自变量增多只会升不降，哪怕新增的变量毫无解释力，<code>R²</code> 也会被它&quot;虚抬&quot;；调整 <code>R²</code> 则对自变量的个数施加了惩罚，每多引入一个变量都要付出自由度代价，因此更适合在模型之间做比较，也更诚实地反映模型的简约性。把调整 <code>R²</code> 的公式拆开看，它的惩罚项来自样本量 n 与自变量个数 p 的比值——当 n 相对 p 很大时，两种 <code>R²</code> 相差无几；当模型趋于饱和（p 逼近 n）时，调整 <code>R²</code> 会明显低于 <code>R²</code>，甚至变为负，提示模型在&quot;过拟合&quot;边缘。当某个自变量的 <code>SIG</code> 大于 0.05，意味着在已纳入其他变量的模型中，它的独立线性贡献不足以与随机波动区分开，此时不宜引用其斜率作结论，应考虑剔除或重新审视变量定义。</p><p><strong>ANOVA 表</strong>汇报的是整个回归（所有自变量合在一起）的显著性，其 F 检验回答&quot;模型整体是否优于仅凭均值预测&quot;。它不针对单个自变量，单个自变量的显著性要看系数表的 <code>SIG</code>。</p><p>共线性是多元回归特有的隐患。当自变量之间彼此高度相关，各自的系数估计会变得不稳定、标准误膨胀、符号难以解释。容忍度（TOL）反映某个自变量不能被其余自变量线性解释的比例，数值等于 1 减去该变量对其余自变量回归的决定系数；容忍度越低，共线性越严重。经验上容忍度低于 0.1（保守些也会看 0.2）往往提示问题，其倒数 VIF 超过 10（宽松些看 5）通常视为共线性信号。两者一体两面，报告时择一即可，但初学者同时列出更便于核对。值得注意的是，共线性损害的是&quot;解释&quot;，却不必然损害&quot;预测&quot;——即便系数摇摆不定，模型对样本内 Y 的整体拟合仍可能不错，因此不能仅凭 <code>R²</code> 高就推断每个自变量都可靠。</p><h2 id="_7-5-回归诊断与限制" tabindex="-1">7.5 回归诊断与限制 <a class="header-anchor" href="#_7-5-回归诊断与限制" aria-label="Permalink to &quot;7.5 回归诊断与限制&quot;">​</a></h2><p>线性回归的有效性依赖若干前提：残差近似正态、方差齐性（残差的散布不随预测值变化）、自变量与因变量之间确为线性关系，以及各案观测相互独立。按理说，这些前提该由回归过程一并报告，让使用者一次看清模型是否可靠。</p><p>然而必须如实说明一个关键事实：<strong>PSPP 的 <code>REGRESSION</code> 并未提供 <code>/SCATTERPLOT</code>、<code>/RESIDUALS</code>、<code>/CASEWISE</code>、<code>/OUTLIERS</code> 等专用诊断子命令，也没有 Durbin-Watson 统计量、Cook 距离的直接输出。</strong> 这部分在 PSPP 手册中并未逐项覆盖，属于通用统计知识，而非 PSPP 特有的可操作步骤。因此，任何把残差诊断写成&quot;在 PSPP 里点几下即可完成&quot;的描述都是不准确的；在 PSPP 当前版本中，这类诊断必须手工处理。</p><p>PSPP 留给我们的唯一内置出口是 <code>/SAVE=RESID</code>（常配合 <code>PRED</code>），把残差 <code>RES1</code> 与预测值 <code>PRED1</code> 落回活动数据集，之后再用通用过程自行检视。下面给出一条完整、可在 PSPP 中直接运行的示例，仍以 7.2 的身高—体重数据演示：先拟合简单回归并写出残差，再用 <code>EXAMINE</code> 检查残差的正态性。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATA LIST LIST /id (A4) height (F4.0) weight (F4.0).</span></span>
<span class="line"><span>BEGIN DATA.</span></span>
<span class="line"><span>P001 172 65</span></span>
<span class="line"><span>P002 168 60</span></span>
<span class="line"><span>P003 180 75</span></span>
<span class="line"><span>P004 160 52</span></span>
<span class="line"><span>P005 175 70</span></span>
<span class="line"><span>P006 165 58</span></span>
<span class="line"><span>P007 178 72</span></span>
<span class="line"><span>P008 158 50</span></span>
<span class="line"><span>P009 170 63</span></span>
<span class="line"><span>P010 182 78</span></span>
<span class="line"><span>P011 166 57</span></span>
<span class="line"><span>P012 174 68</span></span>
<span class="line"><span>END DATA.</span></span>
<span class="line"><span>VARIABLE LABELS height &#39;身高(厘米)&#39; weight &#39;体重(千克)&#39;.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>* 拟合简单回归，并将残差与预测值写回数据集</span></span>
<span class="line"><span>REGRESSION /VARIABLES=height weight /DEPENDENT=weight</span></span>
<span class="line"><span>           /STATISTICS=DEFAULTS</span></span>
<span class="line"><span>           /SAVE=PRED RESID /METHOD=ENTER.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>* 检视残差正态性：直方图 + 正态概率图（自动附带 Shapiro-Wilk 检验）</span></span>
<span class="line"><span>EXAMINE RES1 /PLOT=HISTOGRAM NPPLOT /STATISTICS=DESCRIPTIVES.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>* 检视方差齐性与线性：残差对预测值散点，应呈围绕 0 线的无规律横向带</span></span>
<span class="line"><span>GRAPH /SCATTERPLOT = PRED1 WITH RES1.</span></span></code></pre></div><p>按上面的语法跑完后，可作如下解读：</p><ul><li><strong>残差正态性</strong>：<code>EXAMINE</code> 的 <code>/PLOT=HISTOGRAM</code> 给出残差直方图，<code>NPPLOT</code> 给出正态概率图；只要请求了图形，PSPP 会自动执行 Shapiro-Wilk 正态性检验。若 Shapiro-Wilk 的 p 值大于 α（如 0.05），通常不拒绝残差正态的假定，可认为正态性前提基本满足。直方图若明显偏斜或出现厚尾，则提示正态性可能受损。</li><li><strong>方差齐性与线性</strong>：落在 <code>GRAPH /SCATTERPLOT = PRED1 WITH RES1</code> 这张残差对预测值的散点图上。若点是围绕 0 线的随机云团、上下宽度基本恒定，则方差齐性、线性两项假设皆可接受；若出现喇叭口（一侧散开）、弧形弯曲或明显斜带，则分别暗示异方差、非线性或遗漏变量。</li></ul><p>下面三条概念属于通用统计知识（［手册未覆盖，说明为通用统计知识］），PSPP 不提供直接输出，列在此处供读者判断模型健康度：</p><ul><li><strong>残差独立性</strong>：理想情况下，一个个案的残差不应预示着另一个个案的残差，尤其对时间序列数据要警惕相邻残差正相关。侦测它的 Durbin-Watson 统计量在 PSPP 中没有现成输出，需借 <code>/SAVE=RESID</code> 取出残差后用其他工具手算。</li><li><strong>异方差</strong>：残差的方差应不随预测值水平变化；若散点呈喇叭口，小预测值处紧凑、大预测值处发散，则违背方差齐性。可考虑对因变量取对数等变换，或改用对异方差稳健的估计。</li><li><strong>多重共线性</strong>：已在 7.4 节讨论，用 <code>TOL</code>/<code>VIF</code> 窥探；它只影响系数估计的稳定性，不直接影响模型整体的预测能力。</li></ul><p>一旦图形发出警示，应回到数据层面处置，而这部分在 PSPP 里同样要手工完成：异方差可考虑对因变量取对数等变换（<code>COMPUTE</code> 生成新变量后重新拟合），或改用对异方差稳健的估计思路；非线性可尝试加入自变量的平方项、交互项（<code>COMPUTE</code> 生成后纳入 <code>/VARIABLES</code>）；怀疑遗漏变量则补充测量或换用 <code>GLM</code> 纳入更多预测变量。PSPP 的 <code>REGRESSION</code> 仅提供建模与 <code>/SAVE</code> 出口，变换、稳健处理与更复杂的设定都需在回归前后用 <code>COMPUTE</code>、<code>GLM</code> 等另行完成，不能指望一条 <code>REGRESSION</code> 命令把诊断与补救打包做完。</p><p>需要特别强调两个子命令的生效条件，以免误用：<code>CI</code>（置信区间）仅在同时选定 <code>COEFF</code> 时才有效，单独写 <code>CI</code> 而不带 <code>COEFF</code> 不会产出区间；<code>TOL</code> 同样仅在 <code>COEFF</code> 被选中的前提下有效。也就是说，若想得到系数的 95% 置信区间，应写作：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>REGRESSION /VARIABLES=height weight age /DEPENDENT=weight</span></span>
<span class="line"><span>           /STATISTICS=COEFF CI(0.95) TOL</span></span>
<span class="line"><span>           /SAVE=PRED RESID /METHOD=ENTER.</span></span></code></pre></div><p>把回归结果讲给非专业读者，关键是把系数翻译成人话，并交代清楚&quot;能说什么、不能说什么&quot;。一份清晰的报告通常先说关联是否存在，再说预测关系（&quot;身高每增高 1 厘米，体重平均增加约 B 千克&quot;），最后说解释力（<code>R²</code> 回答了百分之几的变异被解释）。决定系数 <code>R²</code> 是直接讲&quot;百分之几的变动能被解释&quot;最直观的效应量，比抛出一个相关系数更易被记住；系数的可靠性则由各自的 <code>SIG</code> 与（如已请求）95% 置信区间支撑。</p><p>无论相关还是回归，输出的都只是统计关联，不能自动升级为因果断言。若要论证因果，还需实验设计或理论支撑，这超出 <code>CORRELATIONS</code> 与 <code>REGRESSION</code> 本身的本领。最后，诚实地写明诊断结论——残差是否近似正态、方差是否齐性，以及 PSPP 未能直接给出的 Durbin-Watson 与 Cook 距离如何以 <code>/SAVE=RESID</code> 配合其他工具补做——能让一份回归报告经得起推敲。</p>`,55)])])}const I=s(p,[["render",c]]);export{r as __pageData,I as default};
